#include <bits/stdc++.h>
#include <gaden/RunningSimulation.hpp>
#include <gaden/internal/Serialization.hpp>
#include <gaden/internal/compression.hpp>
#include <nlohmann/json.hpp>
using json=nlohmann::json;namespace fs=std::filesystem;
json readj(fs::path p){std::ifstream f(p);json j;f>>j;return j;}
std::vector<std::string> split(std::string l){if(!l.empty()&&l.back()=='\r')l.pop_back();std::stringstream s(l);std::string t;std::vector<std::string>v;while(std::getline(s,t,','))v.push_back(t);return v;}
struct Q{std::string id,group;int stop,point;double time;gaden::Vector3 xyz;};
std::vector<Q> queries(fs::path p){std::ifstream f(p);std::string l;std::getline(f,l);auto h=split(l);std::map<std::string,int>ix;for(int i=0;i<h.size();i++)ix[h[i]]=i;std::vector<Q>q;while(std::getline(f,l)){auto a=split(l);if(a.size()!=h.size())continue;q.push_back({a[ix["query_id"]],a[ix["group"]],std::stoi(a[ix["stop"]]),std::stoi(a[ix["point_id"]]),std::stod(a[ix["physical_s"]]),{std::stof(a[ix["x"]]),std::stof(a[ix["y"]]),std::stof(a[ix["z"]])}});}return q;}
void snapshot(gaden::Simulation&sim,fs::path dest){std::vector<uint8_t>raw(gaden::serialization::defaultBufferSize),out(raw.size()+1024);gaden::serialization::BufferWriter w((char*)raw.data(),raw.size());w.Write(&gaden::versionMajor);w.Write(&gaden::versionMinor);w.Write(&sim.config->environment.description);gaden::GasSource::SerializeBinary(w,sim.simulationMetadata.source);w.Write(&sim.simulationMetadata.constants);int idx=sim.config->windSequence.GetCurrentIndex();w.Write(&idx);std::string payloadMode="filaments";w.WriteString(&payloadMode);w.WriteVector(&sim.GetFilaments());auto mode=gaden::serialization::CompressionMode::ZLIB;size_t n=w.currentOffset();zlib::uLongf len=out.size();if(zlib::compress2(out.data(),&len,raw.data(),n,1)!=Z_OK)throw std::runtime_error("compression failed");std::ofstream f(dest,std::ios::binary);f.write(gaden::serialization::resultIdentifier,sizeof(gaden::serialization::resultIdentifier));f.write((char*)&mode,sizeof(mode));f.write((char*)&n,sizeof(n));f.write((char*)out.data(),len);}
struct CauseSimulation:gaden::RunningSimulation{
 json coarse;std::string mode;
 CauseSimulation(Parameters p,std::shared_ptr<gaden::EnvironmentConfiguration>c,const json&t):RunningSimulation(p,c),mode(t["mode"].get<std::string>()){if(mode=="plane_coarse")coarse=readj(t["coarse_scene"].get<std::string>());}
 gaden::Vector3 SampleWind(const gaden::Vector3i&indices)const override{if(mode=="fixed_uv"){auto current=RunningSimulation::SampleWind(indices);auto plane=indices;plane.z=config->environment.coordsToIndices(simulationMetadata.source->sourcePosition).z;auto fixed=RunningSimulation::SampleWind(plane);return {fixed.x,fixed.y,current.z};}if(mode!="plane_coarse")return RunningSimulation::SampleWind(indices);auto xyz=config->environment.coordsOfCellCenter(indices);float x0=coarse["origin"][0],y0=coarse["origin"][1],cs=coarse["cell_size"];int nx=coarse["nx"],ny=coarse["ny"];int x=(xyz.x-x0)/cs,y=(xyz.y-y0)/cs;if(x<0||x>=nx||y<0||y>=ny)return {0,0,0};auto v=coarse["wind_xy"][x+nx*y];return {v[0].get<float>(),v[1].get<float>(),0};}
};
int main(int argc,char**argv){try{
 if(argc!=6)throw std::runtime_error("cause_driver task map wind queries out");auto task=readj(argv[1]);fs::path out=argv[5];fs::create_directories(out);fs::create_directories(out/"anchors");
 auto conf=std::make_shared<gaden::EnvironmentConfiguration>();if(conf->environment.ReadFromFile(argv[2])!=gaden::ReadResult::OK)throw std::runtime_error("bad map");conf->windSequence.Initialize({fs::path(argv[3])},conf->environment.numCells(),{});
 auto xyz=task["source_xyz"];gaden::RunningSimulation::Parameters p;p.source=std::make_shared<gaden::PointSource>();p.source->sourcePosition={xyz[0],xyz[1],xyz[2]};p.source->gasType=static_cast<gaden::GasType>(10);p.deltaTime=.1f;p.windIterationDeltaTime=1;p.temperature=298;p.pressure=1;p.filamentPPMcenter_initial=10;p.filamentInitialSigma=10;p.filamentGrowthGamma=15;p.filamentNoise_std=task.value("noise_input",.015f);p.numFilaments_sec=10;p.expectedNumIterations=2400;p.saveResults=false;p.preCalculateConcentrations=false;p.windLoop=gaden::LoopConfig{};
 if(conf->environment.at(p.source->sourcePosition)!=gaden::Environment::CellState::Free)throw std::runtime_error("source not free");CauseSimulation sim(p,conf,task);auto qs=queries(argv[4]);std::vector<size_t>order(qs.size());std::iota(order.begin(),order.end(),0);std::stable_sort(order.begin(),order.end(),[&](int a,int b){return qs[a].time<qs[b].time;});std::map<int,std::string>last;for(auto i:order)if(qs[i].group=="historical")last[qs[i].stop]=qs[i].id;
 std::vector<float>values(qs.size());std::vector<int>binding(qs.size());std::vector<double>time(qs.size());size_t cursor=0;uint64_t outside_samples=0,filament_samples=0;float minz=1e30f,maxz=-1e30f;std::ofstream timeline(out/"TIMELINE.csv");timeline<<"step,pre_time_s,post_time_s,filaments,centers_outside_physical_extent,min_z,max_z\n"<<std::setprecision(17);
 for(int step=0;step<2400;step++){
  double pre=sim.GetCurrentTime();sim.AdvanceTimestep();double post=sim.GetCurrentTime();int outside=0;float lo=1e30f,hi=-1e30f;
  for(const auto&f:sim.GetFilaments()){bool bad=glm::any(glm::lessThan(f.position,conf->environment.description.minCoord))||glm::any(glm::greaterThanEqual(f.position,conf->environment.description.maxCoord));outside+=bad;lo=std::min(lo,f.position.z);hi=std::max(hi,f.position.z);}
  outside_samples+=outside;filament_samples+=sim.GetFilaments().size();minz=std::min(minz,lo);maxz=std::max(maxz,hi);timeline<<step<<','<<pre<<','<<post<<','<<sim.GetFilaments().size()<<','<<outside<<','<<lo<<','<<hi<<'\n';
  while(cursor<order.size()&&qs[order[cursor]].time<post-1e-8){auto i=order[cursor];if(qs[i].time<pre-1e-6)throw std::runtime_error("clock mismatch");values[i]=sim.SampleConcentration(qs[i].xyz);binding[i]=step;time[i]=pre;if(qs[i].group=="historical"&&last[qs[i].stop]==qs[i].id)snapshot(sim,out/"anchors"/("stop_"+std::to_string(qs[i].stop)));cursor++;}
 }
 if(cursor!=qs.size())throw std::runtime_error("unread queries");std::ofstream r(out/"RESPONSES.csv");r<<"query_id,point_id,physical_s,physical_step,snapshot_time_s,x,y,z,raw_gas_ppm\n"<<std::setprecision(17);for(size_t i=0;i<qs.size();i++)r<<qs[i].id<<','<<qs[i].point<<','<<qs[i].time<<','<<binding[i]<<','<<time[i]<<','<<qs[i].xyz.x<<','<<qs[i].xyz.y<<','<<qs[i].xyz.z<<','<<values[i]<<'\n';
 json j={{"status","QUERY_ONLY_NATIVE_KERNEL_COMPLETED"},{"mode",task["mode"]},{"strict_bounds",task["strict_bounds"]},{"source_xyz",xyz},{"queries",qs.size()},{"steps",2400},{"final_time_s",sim.GetCurrentTime()},{"outside_particle_time_samples",outside_samples},{"all_particle_time_samples",filament_samples},{"min_z",minz},{"max_z",maxz},{"noise_effective",sim.GetParameters().filamentNoise_std},{"no_full_world_archive",true},{"anchor_snapshots",last.size()}};std::ofstream(out/"RESULT.json")<<std::setw(2)<<j<<'\n';std::cout<<j<<'\n';
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
